const fs = require("fs");
const depts = ["access","data","dependencies","injection","platform","secrets"];
const all = [];
for (const d of depts) {
  const arr = JSON.parse(fs.readFileSync(`findings/${d}.json`, "utf8"));
  for (const f of arr) { f.__dept = d; all.push(f); }
}
console.log("total raw:", all.length);
// group by file+line+cwe
const groups = new Map();
for (const f of all) {
  const key = f.file + "|" + f.line + "|" + f.cwe;
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(f);
}
const dupGroups = [...groups.entries()].filter(([k,v]) => v.length > 1);
console.log("dup groups:", dupGroups.length);
for (const [k, v] of dupGroups) {
  console.log("---", k);
  for (const f of v) console.log("  ", f.id, f.severity, f.confidence, f.__dept);
}
' 
","description":"Programmatically find all duplicate groups by file+line+cwe"}

